import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxDivider,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

export default function RegistrationWizard({ onSubmit }: { onSubmit: (data: RegistrationData) => void }) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    phone: '',
    country: '',
    city: '',
    street: '',
    comment: '',
  });

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const contactsReady = data.name.trim() !== '' && data.email.includes('@');
  const addressReady = data.country !== '' && data.city.trim() !== '' && data.street.trim() !== '';
  const canGoNext = step === 0 ? contactsReady : step === 1 ? addressReady : true;

  const countryLabel = countries.find((c) => c.value === data.country)?.label ?? '—';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24, maxWidth: 560 }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Имя и фамилия"
            required
            autoComplete="name"
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            autoComplete="tel"
            helperText="Необязательно, для связи по доставке"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
          />
          <JxInputField
            label="Улица, дом, квартира"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
          />
          <JxTextareaField
            label="Комментарий к адресу"
            rows={3}
            maxLength={300}
            helperText={`${data.comment.length}/300`}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxAlert intent="info" title="Проверьте данные">
            После отправки изменить заявку можно будет только через поддержку.
          </JxAlert>
          <JxDivider label="Контакты" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.name}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.email}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Телефон</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.phone ? `+7${data.phone}` : '—'}</dd>
          </dl>
          <JxDivider label="Адрес" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Страна</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{countryLabel}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.city}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Адрес</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.street}</dd>
            {data.comment && (
              <>
                <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
                <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.comment}</dd>
              </>
            )}
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

